<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/admin.php';send_cors_headers();require_admin();$db=get_db();$queries=['vendor_applications'=>'SELECT id,reference,status,submitted_at created_at FROM vendor_applications WHERE status IN ("submitted","under_review") ORDER BY submitted_at LIMIT 50','products'=>'SELECT id,name,status,updated_at created_at FROM products WHERE status IN ("pending_review","under_review") ORDER BY updated_at LIMIT 50','claims'=>'SELECT id,claim_statement,status,created_at FROM (SELECT id,claim_statement,review_status status,created_at FROM sustainability_claims) x WHERE status IN ("pending_review","evidence_requested") ORDER BY created_at LIMIT 50','refunds'=>'SELECT id,reason,status,created_at FROM refunds WHERE status IN ("recommended","approved","processing") ORDER BY created_at LIMIT 50','payouts'=>'SELECT id,amount,status,requested_at created_at FROM payout_requests WHERE status IN ("requested","maker_approved","processing") ORDER BY requested_at LIMIT 50','support'=>'SELECT id,subject,status,created_at FROM support_tickets WHERE status NOT IN ("resolved","closed") ORDER BY FIELD(priority,"urgent","high","normal","low"),created_at LIMIT 50','influencers'=>'SELECT id,handle,status,created_at FROM influencers WHERE status="pending_review" ORDER BY created_at LIMIT 50'];$queue=[];foreach($queries as $key=>$sql)$queue[$key]=$db->query($sql)->fetchAll();json_response(200,['success'=>true,'queue'=>$queue]);
